  1	package shop;
  2	
  3	import com.zaxxer.hikari.HikariConfig;
  4	import com.zaxxer.hikari.HikariDataSource;
  5	import shop.persistence.PostgresStore;
  6	import shop.persistence.Schema;
  7	import shop.shipping.TransLogGateway;
  8	
  9	import java.time.Clock;
 10	
 11	public final class Main {
 12	    private Main() {
 13	    }
 14	
 15	    public static void main(String[] args) throws Exception {
 16	        HikariDataSource dataSource = connect();
 17	        Schema.init(dataSource);
 18	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "8080"));
 19	        App.create(new PostgresStore(dataSource), new TransLogGateway(System.getenv("TRANSLOG_URL")), Clock.systemUTC())
 20	                .start(port);
 21	    }
 22	
 23	    /** The database may still be starting when the service does, so it retries for a while. */
 24	    private static HikariDataSource connect() throws InterruptedException {
 25	        HikariConfig config = new HikariConfig();
 26	        config.setJdbcUrl(jdbcUrl(System.getenv("DB_URL")));
 27	        config.setUsername(System.getenv("DB_USER"));
 28	        config.setPassword(System.getenv("DB_PASSWORD"));
 29	        config.setMaximumPoolSize(10);
 30	        for (int attempt = 1; ; attempt++) {
 31	            try {
 32	                config.setInitializationFailTimeout(1);
 33	                return new HikariDataSource(config);
 34	            } catch (RuntimeException e) {
 35	                if (attempt >= 30) {
 36	                    throw e;
 37	                }
 38	                Thread.sleep(2000);
 39	            }
 40	        }
 41	    }
 42	
 43	    private static String jdbcUrl(String url) {
 44	        if (url == null || url.startsWith("jdbc:")) {
 45	            return url;
 46	        }
 47	        return "jdbc:" + url.replaceFirst("^postgres://", "postgresql://");
 48	    }
 49	}
 50	package shop;
 51	
 52	import io.javalin.Javalin;
 53	import shop.checkout.CheckoutCalculator;
 54	import shop.coupon.Buy3Pay2Coupon;
 55	import shop.coupon.Coupon;
 56	import shop.coupon.FreeShippingCoupon;
 57	import shop.coupon.Minus50Coupon;
 58	import shop.coupon.Welcome10Coupon;
 59	import shop.notification.Notifier;
 60	import shop.order.CreditReaction;
 61	import shop.order.OrderService;
 62	import shop.order.PaymentApprovedNoticeReaction;
 63	import shop.payment.BankSlipPayment;
 64	import shop.payment.CreditCardPayment;
 65	import shop.payment.PaymentOption;
 66	import shop.payment.PixPayment;
 67	import shop.persistence.Store;
 68	import shop.shipping.CarrierGateway;
 69	import shop.shipping.CarrierShipping;
 70	import shop.shipping.CourierShipping;
 71	import shop.shipping.ShippingOption;
 72	import shop.shipping.StorePickupShipping;
 73	import shop.web.Routes;
 74	
 75	import java.time.Clock;
 76	import java.util.List;
 77	import java.util.Map;
 78	import java.util.function.Function;
 79	import java.util.stream.Collectors;
 80	
 81	/** Wires the service together. Adding a shipping option, coupon, payment method or payment reaction is a line here. */
 82	public final class App {
 83	    private App() {
 84	    }
 85	
 86	    public static Javalin create(Store store, CarrierGateway translog, Clock clock) {
 87	        Map<String, ShippingOption> shipping = byCode(List.of(
 88	                new CarrierShipping("ECONOMY", "STD", translog),
 89	                new CarrierShipping("EXPRESS", "EXP", translog),
 90	                new StorePickupShipping(),
 91	                new CourierShipping()), ShippingOption::code);
 92	        Map<String, Coupon> coupons = byCode(List.of(
 93	                new Welcome10Coupon(), new Minus50Coupon(), new FreeShippingCoupon(), new Buy3Pay2Coupon()), Coupon::code);
 94	        Map<String, PaymentOption> payments = byCode(List.of(
 95	                new PixPayment(), new CreditCardPayment(), new BankSlipPayment()), PaymentOption::code);
 96	
 97	        Notifier notifier = new Notifier();
 98	        OrderService orders = new OrderService(store, new CheckoutCalculator(shipping, coupons, payments), notifier,
 99	                List.of(new CreditReaction(), new PaymentApprovedNoticeReaction(notifier)), clock);
100	
101	        Javalin app = Javalin.create();
102	        new Routes(orders, new QueryService(store)).register(app);
103	        return app;
104	    }
105	
106	    private static <T> Map<String, T> byCode(List<T> items, Function<T, String> code) {
107	        return items.stream().collect(Collectors.toUnmodifiableMap(code, Function.identity()));
108	    }
109	}
110	package shop.web;
111	
112	import com.fasterxml.jackson.core.JsonGenerator;
113	import com.fasterxml.jackson.databind.JsonNode;
114	import com.fasterxml.jackson.databind.ObjectMapper;
115	import com.fasterxml.jackson.databind.SerializationFeature;
116	import com.fasterxml.jackson.databind.node.JsonNodeFactory;
117	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
118	import io.javalin.Javalin;
119	import io.javalin.http.Context;
120	import shop.ApiException;
121	import shop.QueryService;
122	import shop.checkout.CheckoutRequest;
123	import shop.order.OrderService;
124	
125	import java.util.Map;
126	import java.util.function.Supplier;
127	
128	public final class Routes {
129	    private static final ObjectMapper MAPPER = new ObjectMapper()
130	            .registerModule(new JavaTimeModule())
131	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
132	            .enable(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN);
133	
134	    private final OrderService orders;
135	    private final QueryService queries;
136	
137	    public Routes(OrderService orders, QueryService queries) {
138	        this.orders = orders;
139	        this.queries = queries;
140	    }
141	
142	    public void register(Javalin app) {
143	        app.post("/checkout/summary", ctx -> reply(ctx, 200, () -> orders.summary(CheckoutRequest.from(body(ctx)))));
144	        app.post("/orders", ctx -> reply(ctx, 201, () -> orders.register(CheckoutRequest.from(body(ctx)))));
145	        app.get("/orders/{id}", ctx -> reply(ctx, 200, () -> orders.get(ctx.pathParam("id"))));
146	        app.post("/orders/{id}/payment", ctx -> reply(ctx, 200, () -> orders.confirmPayment(ctx.pathParam("id"), body(ctx))));
147	        app.post("/orders/{id}/shipment", ctx -> reply(ctx, 200, () -> orders.ship(ctx.pathParam("id"), body(ctx))));
148	        app.post("/orders/{id}/delivery", ctx -> reply(ctx, 200, () -> orders.deliver(ctx.pathParam("id"))));
149	        app.post("/orders/{id}/cancellation", ctx -> reply(ctx, 200, () -> orders.cancel(ctx.pathParam("id"))));
150	        app.get("/products/{sku}", ctx -> reply(ctx, 200, () -> queries.product(ctx.pathParam("sku"))));
151	        app.get("/customers/{cpf}", ctx -> reply(ctx, 200, () -> queries.customer(ctx.pathParam("cpf"))));
152	        app.get("/customers/{cpf}/notifications", ctx -> reply(ctx, 200, () -> queries.notifications(ctx.pathParam("cpf"))));
153	        app.post("/notifications/{id}/read", ctx -> reply(ctx, 200, () -> queries.markRead(ctx.pathParam("id"))));
154	    }
155	
156	    private static JsonNode body(Context ctx) {
157	        try {
158	            JsonNode node = MAPPER.readTree(ctx.body());
159	            return node != null && node.isObject() ? node : JsonNodeFactory.instance.objectNode();
160	        } catch (Exception e) {
161	            return JsonNodeFactory.instance.objectNode();
162	        }
163	    }
164	
165	    private static void reply(Context ctx, int successStatus, Supplier<Object> action) {
166	        int status = successStatus;
167	        Object payload;
168	        try {
169	            payload = action.get();
170	        } catch (ApiException e) {
171	            status = e.status();
172	            payload = Map.of("error", e.code());
173	        } catch (RuntimeException e) {
174	            e.printStackTrace();
175	            status = 500;
176	            payload = Map.of("error", "INTERNAL_ERROR");
177	        }
178	        try {
179	            ctx.status(status).contentType("application/json").result(MAPPER.writeValueAsString(payload));
180	        } catch (Exception e) {
181	            throw new IllegalStateException(e);
182	        }
183	    }
184	}

