225	    @Override
226	    public <T> T inTransaction(Function<Tx, T> work) {
227	        try (Connection connection = dataSource.getConnection()) {
228	            connection.setAutoCommit(false);
229	            try {
230	                T result = work.apply(new PostgresTx(connection));
231	                connection.commit();
232	                return result;
233	            } catch (Throwable e) {
234	                connection.rollback();
235	                throw e;
236	            }
237	        } catch (SQLException e) {
238	            throw new IllegalStateException(e);
239	        }
240	    }
