283	    private static void update(Connection connection, String sql, Binder binder) {
284	        try (PreparedStatement statement = connection.prepareStatement(sql)) {
285	            binder.bind(statement);
286	            statement.executeUpdate();
287	        } catch (SQLException e) {
288	            throw new IllegalStateException(e);
289	        }
