292	    private static <T> List<T> query(Connection connection, String sql, Binder binder, RowReader<T> reader) {
293	        try (PreparedStatement statement = connection.prepareStatement(sql)) {
294	            binder.bind(statement);
295	            try (ResultSet rows = statement.executeQuery()) {
296	                List<T> result = new ArrayList<>();
297	                while (rows.next()) {
298	                    result.add(reader.read(rows));
299	                }
300	                return result;
301	            }
302	        } catch (SQLException e) {
303	            throw new IllegalStateException(e);
304	        }
305	    }
