  1	package shop.order;
  2	
  3	import com.fasterxml.jackson.databind.JsonNode;
  4	import shop.ApiException;
  5	import shop.checkout.CheckoutCalculator;
  6	import shop.checkout.CheckoutRequest;
  7	import shop.checkout.Summary;
  8	import shop.notification.NotificationType;
  9	import shop.notification.Notifier;
 10	import shop.persistence.Store;
 11	import shop.persistence.Tx;
 12	
 13	import java.time.Clock;
 14	import java.time.Duration;
 15	import java.time.Instant;
 16	import java.time.format.DateTimeParseException;
 17	import java.time.temporal.ChronoUnit;
 18	import java.util.Comparator;
 19	import java.util.List;
 20	import java.util.UUID;
 21	
 22	public final class OrderService {
 23	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
 24	
 25	    private final Store store;
 26	    private final CheckoutCalculator calculator;
 27	    private final Notifier notifier;
 28	    private final List<PaymentConfirmationReaction> reactions;
 29	    private final Clock clock;
 30	
 31	    public OrderService(Store store, CheckoutCalculator calculator, Notifier notifier,
 32	                        List<PaymentConfirmationReaction> reactions, Clock clock) {
 33	        this.store = store;
 34	        this.calculator = calculator;
 35	        this.notifier = notifier;
 36	        this.reactions = reactions;
 37	        this.clock = clock;
 38	    }
 39	
 40	    public Summary summary(CheckoutRequest request) {
 41	        return store.inTransaction(tx -> calculator.calculate(tx, request));
 42	    }
 43	
 44	    public Order register(CheckoutRequest request) {
 45	        return store.inTransaction(tx -> {
 46	            Summary summary = calculator.calculate(tx, request);
 47	            tx.customers().createIfAbsent(request.cpf());
 48	            List<OrderItem> items = request.items().stream()
 49	                    .map(item -> new OrderItem(item.sku(), item.quantity())).toList();
 50	            Order order = new Order(UUID.randomUUID().toString(), request.cpf(), request.email(),
 51	                    OrderStatus.AWAITING_PAYMENT, clock.instant().truncatedTo(ChronoUnit.SECONDS), summary, items, null);
 52	            tx.orders().insert(order);
 53	            return order;
 54	        });
 55	    }
 56	
 57	    public Order get(String id) {
 58	        return store.inTransaction(tx -> tx.orders().find(id).orElseThrow(OrderService::notFound));
 59	    }
 60	
 61	    private record PaymentResult(Order order, String refusal) {
 62	    }
 63	
 64	    public Order confirmPayment(String id, JsonNode body) {
 65	        PaymentResult result = store.inTransaction(tx -> {
 66	            Order order = tx.orders().lock(id).orElseThrow(OrderService::notFound);
 67	            String transactionId = CheckoutRequest.text(body, "transactionId");
 68	            String paidAtText = CheckoutRequest.text(body, "paidAt");
 69	            if (transactionId == null || transactionId.isBlank() || paidAtText == null) {
 70	                throw ApiException.unprocessable("INVALID_ORDER");
 71	            }
 72	            Instant paidAt;
 73	            try {
 74	                paidAt = Instant.parse(paidAtText);
 75	            } catch (DateTimeParseException e) {
 76	                throw ApiException.unprocessable("INVALID_ORDER");
 77	            }
 78	            var previous = tx.paymentNotices().find(id, transactionId);
 79	            if (previous.isPresent()) {
 80	                return new PaymentResult(order, previous.get().refusalCode());
 81	            }
 82	            requireTransition(order, OrderStatus.PAID);
 83	            if (Duration.between(order.createdAt(), paidAt).compareTo(PAYMENT_WINDOW) > 0) {
 84	                return refuse(tx, order, transactionId, "ORDER_EXPIRED");
 85	            }
 86	            if (!reserveStock(tx, order)) {
 87	                return refuse(tx, order, transactionId, "INSUFFICIENT_STOCK");
 88	            }
 89	            Order paid = order.withStatus(OrderStatus.PAID);
 90	            tx.orders().update(paid);
 91	            reactions.forEach(reaction -> reaction.onPaid(tx, paid));
 92	            tx.paymentNotices().insert(new PaymentNotice(id, transactionId, null));
 93	            return new PaymentResult(paid, null);
 94	        });
 95	        if (result.refusal() != null) {
 96	            throw ApiException.conflict(result.refusal());
 97	        }
 98	        return result.order();
 99	    }
100	
101	    public Order ship(String id, JsonNode body) {
102	        return store.inTransaction(tx -> {
103	            Order order = tx.orders().lock(id).orElseThrow(OrderService::notFound);
104	            String trackingCode = CheckoutRequest.text(body, "trackingCode");
105	            if (trackingCode == null || trackingCode.isBlank()) {
106	                throw ApiException.unprocessable("INVALID_ORDER");
107	            }
108	            requireTransition(order, OrderStatus.SHIPPED);
109	            Order shipped = order.withStatus(OrderStatus.SHIPPED).withTrackingCode(trackingCode);
110	            tx.orders().update(shipped);
111	            notifier.notify(tx, shipped, NotificationType.ORDER_SHIPPED);
112	            return shipped;
113	        });
114	    }
115	
116	    public Order deliver(String id) {
117	        return store.inTransaction(tx -> {
118	            Order order = tx.orders().lock(id).orElseThrow(OrderService::notFound);
119	            requireTransition(order, OrderStatus.DELIVERED);
120	            Order delivered = order.withStatus(OrderStatus.DELIVERED);
121	            tx.orders().update(delivered);
122	            return delivered;
123	        });
124	    }
125	
126	    public Order cancel(String id) {
127	        return store.inTransaction(tx -> {
128	            Order order = tx.orders().lock(id).orElseThrow(OrderService::notFound);
129	            requireTransition(order, OrderStatus.CANCELLED);
130	            return cancelOrder(tx, order);
131	        });
132	    }
133	
134	    private PaymentResult refuse(Tx tx, Order order, String transactionId, String code) {
135	        Order cancelled = cancelOrder(tx, order);
136	        tx.paymentNotices().insert(new PaymentNotice(order.id(), transactionId, code));
137	        return new PaymentResult(cancelled, code);
138	    }
139	
140	    /** Cancels the order, undoing what the payment did when it had been confirmed. */
141	    private Order cancelOrder(Tx tx, Order order) {
142	        if (order.status().paymentConfirmed()) {
143	            releaseStock(tx, order);
144	            reactions.forEach(reaction -> reaction.onPaidOrderCancelled(tx, order));
145	        }
146	        Order cancelled = order.withStatus(OrderStatus.CANCELLED);
147	        tx.orders().update(cancelled);
148	        notifier.notify(tx, cancelled, NotificationType.ORDER_CANCELLED);
149	        return cancelled;
150	    }
151	
152	    /** Locks the products (always in SKU order) and takes the stock only if every item is covered. */
153	    private boolean reserveStock(Tx tx, Order order) {
154	        List<OrderItem> items = sorted(order);
155	        for (OrderItem item : items) {
156	            boolean enough = tx.products().lock(item.sku()).map(product -> product.stock() >= item.quantity()).orElse(false);
157	            if (!enough) {
158	                return false;
159	            }
160	        }
161	        items.forEach(item -> tx.products().adjustStock(item.sku(), -item.quantity()));
162	        return true;
163	    }
164	
165	    private void releaseStock(Tx tx, Order order) {
166	        sorted(order).forEach(item -> tx.products().adjustStock(item.sku(), item.quantity()));
167	    }
168	
169	    private static List<OrderItem> sorted(Order order) {
170	        return order.items().stream().sorted(Comparator.comparing(OrderItem::sku)).toList();
171	    }
172	
173	    private static void requireTransition(Order order, OrderStatus target) {
174	        if (!order.status().canMoveTo(target)) {
175	            throw ApiException.conflict("OPERATION_NOT_ALLOWED");
176	        }
177	    }
178	
179	    private static ApiException notFound() {
180	        return ApiException.notFound("ORDER_NOT_FOUND");
181	    }
182	}
