216	public final class PostgresStore implements Store {
217	    private static final ObjectMapper JSON = new ObjectMapper();
218	
219	    private final DataSource dataSource;
220	
221	    public PostgresStore(DataSource dataSource) {
222	        this.dataSource = dataSource;
223	    }
224	
225	    @Override
226	    public <T> T inTransaction(Function<Tx, T> work) {
227	        try (Connection connection = dataSource.getConnection()) {
228	            connection.setAutoCommit(false);
229	            try {
230	                T result = work.apply(new PostgresTx(connection));
231	                connection.commit();
232	                return result;
233	            } catch (Throwable e) {
234	                connection.rollback();
235	                throw e;
236	            }
237	        } catch (SQLException e) {
238	            throw new IllegalStateException(e);
239	        }
240	    }
241	
242	    private static final class PostgresTx implements Tx {
243	        private final Connection connection;
244	
245	        PostgresTx(Connection connection) {
246	            this.connection = connection;
247	        }
248	
249	        @Override
250	        public ProductRepository products() {
251	            return new Products(connection);
252	        }
253	
254	        @Override
255	        public OrderRepository orders() {
256	            return new Orders(connection);
257	        }
258	
259	        @Override
260	        public CustomerRepository customers() {
261	            return new Customers(connection);
262	        }
263	
264	        @Override
265	        public NotificationRepository notifications() {
266	            return new Notifications(connection);
267	        }
268	
269	        @Override
270	        public PaymentNoticeRepository paymentNotices() {
271	            return new PaymentNotices(connection);
272	        }
273	    }
