275	    private interface Binder {
276	        void bind(PreparedStatement statement) throws SQLException;
277	    }
278	
279	    private interface RowReader<T> {
280	        T read(ResultSet row) throws SQLException;
281	    }
282	
283	    private static void update(Connection connection, String sql, Binder binder) {
284	        try (PreparedStatement statement = connection.prepareStatement(sql)) {
285	            binder.bind(statement);
286	            statement.executeUpdate();
287	        } catch (SQLException e) {
288	            throw new IllegalStateException(e);
289	        }
290	    }
291	
292	    private static <T> List<T> query(Connection connection, String sql, Binder binder, RowReader<T> reader) {
293	        try (PreparedStatement statement = connection.prepareStatement(sql)) {
294	            binder.bind(statement);
295	            try (ResultSet rows = statement.executeQuery()) {
296	                List<T> result = new ArrayList<>();
297	                while (rows.next()) {
298	                    result.add(reader.read(rows));
299	                }
300	                return result;
301	            }
302	        } catch (SQLException e) {
303	            throw new IllegalStateException(e);
304	        }
305	    }
306	
307	    private static <T> Optional<T> queryOne(Connection connection, String sql, Binder binder, RowReader<T> reader) {
308	        return query(connection, sql, binder, reader).stream().findFirst();
309	    }
