374	    private record Orders(Connection connection) implements OrderRepository {
375	        private static final String SELECT =
376	                "SELECT id, customer_cpf, email, status, created_at, summary, tracking_code FROM orders WHERE id = ?";
377	
378	        @Override
379	        public void insert(Order order) {
380	            PostgresStore.update(connection,
381	                    "INSERT INTO orders (id, customer_cpf, email, status, created_at, summary, tracking_code) "
382	                            + "VALUES (?, ?, ?, ?, ?, ?, ?)", s -> {
383	                        s.setString(1, order.id());
384	                        s.setString(2, order.customerCpf());
385	                        s.setString(3, order.email());
386	                        s.setString(4, order.status().name());
387	                        s.setObject(5, OffsetDateTime.ofInstant(order.createdAt(), ZoneOffset.UTC));
388	                        s.setString(6, toJson(order.summary()));
389	                        s.setString(7, order.trackingCode());
390	                    });
391	            for (OrderItem item : order.items()) {
392	                PostgresStore.update(connection, "INSERT INTO order_items (order_id, sku, quantity) VALUES (?, ?, ?)", s -> {
393	                    s.setString(1, order.id());
394	                    s.setString(2, item.sku());
395	                    s.setInt(3, item.quantity());
396	                });
397	            }
398	        }
