400	        @Override
401	        public Optional<Order> find(String id) {
402	            return queryOne(connection, SELECT, s -> s.setString(1, id), this::read);
403	        }
404	
405	        @Override
406	        public Optional<Order> lock(String id) {
407	            return queryOne(connection, SELECT + " FOR UPDATE", s -> s.setString(1, id), this::read);
408	        }
409	
410	        @Override
411	        public void update(Order order) {
412	            PostgresStore.update(connection, "UPDATE orders SET status = ?, tracking_code = ? WHERE id = ?", s -> {
413	                s.setString(1, order.status().name());
414	                s.setString(2, order.trackingCode());
415	                s.setString(3, order.id());
416	            });
417	        }
418	
419	        @Override
420	        public boolean hasConfirmedPurchase(String cpf) {
421	            return queryOne(connection,
422	                    "SELECT 1 FROM orders WHERE customer_cpf = ? AND status IN ('PAID', 'SHIPPED', 'DELIVERED') LIMIT 1",
423	                    s -> s.setString(1, cpf), row -> 1).isPresent();
424	        }
425	
426	        private Order read(ResultSet row) throws SQLException {
427	            String id = row.getString("id");
428	            List<OrderItem> items = query(connection,
429	                    "SELECT sku, quantity FROM order_items WHERE order_id = ? ORDER BY sku",
430	                    s -> s.setString(1, id), r -> new OrderItem(r.getString("sku"), r.getInt("quantity")));
431	            try {
432	                return new Order(id, row.getString("customer_cpf"), row.getString("email"),
433	                        OrderStatus.valueOf(row.getString("status")),
434	                        row.getObject("created_at", OffsetDateTime.class).toInstant(),
435	                        JSON.readValue(row.getString("summary"), Summary.class), items, row.getString("tracking_code"));
436	            } catch (JsonProcessingException e) {
437	                throw new IllegalStateException(e);
438	            }
439	        }
440	
441	        private static String toJson(Summary summary) {
442	            try {
443	                return JSON.writeValueAsString(summary);
444	            } catch (JsonProcessingException e) {
445	                throw new IllegalStateException(e);
446	            }
447	        }
448	    }
