523	/** Creates what the service needs in an empty database and loads the initial catalog. Safe to run on two machines at once. */
524	public final class Schema {
525	    private static final long LOCK_KEY = 7_340_011L;
526	
527	    private static final List<String> DDL = List.of(
528	            """
529	            CREATE TABLE IF NOT EXISTS products (
530	                sku text PRIMARY KEY,
531	                name text NOT NULL,
532	                price numeric(12,2) NOT NULL,
533	                weight_kg numeric(10,2) NOT NULL,
534	                stock integer NOT NULL CHECK (stock >= 0),
535	                discontinued boolean NOT NULL)""",
536	            """
537	            CREATE TABLE IF NOT EXISTS customers (
538	                cpf text PRIMARY KEY,
539	                credit_balance numeric(12,2) NOT NULL DEFAULT 0)""",
540	            """
541	            CREATE TABLE IF NOT EXISTS orders (
542	                id text PRIMARY KEY,
543	                customer_cpf text NOT NULL REFERENCES customers(cpf),
544	                email text NOT NULL,
545	                status text NOT NULL,
546	                created_at timestamptz NOT NULL,
547	                summary text NOT NULL,
548	                tracking_code text)""",
549	            "CREATE INDEX IF NOT EXISTS orders_customer_idx ON orders (customer_cpf, status)",
550	            """
551	            CREATE TABLE IF NOT EXISTS order_items (
552	                order_id text NOT NULL REFERENCES orders(id),
553	                sku text NOT NULL,
554	                quantity integer NOT NULL,
555	                PRIMARY KEY (order_id, sku))""",
556	            """
557	            CREATE TABLE IF NOT EXISTS notifications (
558	                seq bigserial PRIMARY KEY,
559	                id text NOT NULL UNIQUE,
560	                customer_cpf text NOT NULL,
561	                type text NOT NULL,
562	                order_id text NOT NULL,
563	                status text NOT NULL)""",
564	            "CREATE INDEX IF NOT EXISTS notifications_customer_idx ON notifications (customer_cpf, seq)",
565	            """
566	            CREATE TABLE IF NOT EXISTS payment_notices (
567	                order_id text NOT NULL,
568	                transaction_id text NOT NULL,
569	                refusal text,
570	                PRIMARY KEY (order_id, transaction_id))""");
571	
572	    private Schema() {
573	    }
574	
575	    public static void init(DataSource dataSource) throws SQLException {
576	        try (Connection connection = dataSource.getConnection()) {
577	            connection.setAutoCommit(true);
578	            try (PreparedStatement lock = connection.prepareStatement("SELECT pg_advisory_lock(?)")) {
579	                lock.setLong(1, LOCK_KEY);
580	                lock.execute();
581	            }
582	            try {
583	                try (Statement statement = connection.createStatement()) {
584	                    for (String ddl : DDL) {
585	                        statement.execute(ddl);
586	                    }
587	                }
588	                for (Product product : InitialCatalog.PRODUCTS) {
589	                    try (PreparedStatement insert = connection.prepareStatement(
590	                            "INSERT INTO products (sku, name, price, weight_kg, stock, discontinued) "
591	                                    + "VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT (sku) DO NOTHING")) {
592	                        insert.setString(1, product.sku());
593	                        insert.setString(2, product.name());
594	                        insert.setBigDecimal(3, product.price());
595	                        insert.setBigDecimal(4, product.weightKg());
596	                        insert.setInt(5, product.stock());
597	                        insert.setBoolean(6, product.discontinued());
598	                        insert.executeUpdate();
599	                    }
600	                }
601	            } finally {
602	                try (PreparedStatement unlock = connection.prepareStatement("SELECT pg_advisory_unlock(?)")) {
603	                    unlock.setLong(1, LOCK_KEY);
604	                    unlock.execute();
605	                }
606	            }
607	        }
608	    }
609	}
