144	import com.fasterxml.jackson.databind.JsonNode;
145	
146	import java.util.ArrayList;
147	import java.util.List;
148	
149	/**
150	 * The purchase data as it arrived. Fields are kept raw (null when missing or of the wrong type)
151	 * so that the calculator can report problems in the agreed order.
152	 */
153	public record CheckoutRequest(
154	        String cpf,
155	        String email,
156	        List<Item> items,
157	        String zipCode,
158	        String region,
159	        String shippingMethod,
160	        String coupon,
161	        String paymentMethod,
162	        int installments,
163	        String clubTier) {
164	
165	    public record Item(String sku, Integer quantity) {
166	    }
167	
168	    public static CheckoutRequest from(JsonNode body) {
169	        JsonNode customer = body.path("customer");
