157	
158	import shop.Money;
159	
160	import java.math.BigDecimal;
161	import java.math.MathContext;
162	
163	public final class CreditCardPayment implements PaymentOption {
164	    private static final int MAX_INSTALLMENTS = 12;
165	    private static final int MAX_INTEREST_FREE = 3;
166	    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
167	
168	    @Override
169	    public String code() {
170	        return "CREDIT_CARD";
171	    }
172	
173	    @Override
174	    public boolean acceptsInstallments(int installments) {
175	        return installments >= 1 && installments <= MAX_INSTALLMENTS;
176	    }
177	
178	    @Override
179	    public boolean availableFor(BigDecimal orderTotal) {
180	        return true;
181	    }
182	
183	    @Override
184	    public PaymentCharge charge(BigDecimal orderTotal, int installments, boolean couponInformed) {
185	        BigDecimal count = BigDecimal.valueOf(installments);
186	        if (installments <= MAX_INTEREST_FREE) {
187	            return new PaymentCharge(orderTotal, Money.round(orderTotal.divide(count, MathContext.DECIMAL128)));
188	        }
189	        // Price table: total * i / (1 - (1 + i)^-n)
190	        BigDecimal growth = BigDecimal.ONE.add(MONTHLY_RATE).pow(installments);
191	        BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(growth, MathContext.DECIMAL128));
192	        BigDecimal installment = Money.round(orderTotal.multiply(MONTHLY_RATE).divide(divisor, MathContext.DECIMAL128));
193	        return new PaymentCharge(installment.multiply(count), installment);
194	    }
195	}
