import com.sun.net.httpserver.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

public class Stub {
    record Rule(int status, String body, long delayMs) {}
    static final Map<String, Rule> rules = new ConcurrentHashMap<>();
    static volatile Rule fallback = new Rule(200, "{\"price_cents\":3310,\"eta_hours\":41}", 0);
    static final List<String> log = Collections.synchronizedList(new ArrayList<>());

    static Map<String,String> q(String raw) {
        Map<String,String> m = new HashMap<>();
        if (raw == null) return m;
        for (String p : raw.split("&")) { int i = p.indexOf('='); if (i>0) m.put(URLDecoder.decode(p.substring(0,i), StandardCharsets.UTF_8), URLDecoder.decode(p.substring(i+1), StandardCharsets.UTF_8)); }
        return m;
    }
    static void send(HttpExchange ex, int st, String body) throws IOException {
        byte[] b = body.getBytes(StandardCharsets.UTF_8);
        ex.getResponseHeaders().add("Content-Type", "application/json");
        ex.sendResponseHeaders(st, b.length); ex.getResponseBody().write(b); ex.close();
    }
    public static void main(String[] a) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress(Integer.parseInt(a[0])), 50);
        s.setExecutor(Executors.newCachedThreadPool());
        s.createContext("/v2/quote", ex -> {
            String raw = ex.getRequestURI().getRawQuery();
            Map<String,String> m = q(raw);
            log.add(raw);
            String key = m.get("zip") + "|" + m.get("service");
            Rule r = rules.getOrDefault(key, rules.getOrDefault(m.get("zip"), fallback));
            try { if (r.delayMs() > 0) Thread.sleep(r.delayMs()); } catch (InterruptedException e) {}
            try { send(ex, r.status(), r.body()); } catch (IOException e) {}
        });
        // /set?key=zip[|service]&status=200&delay=0  body=request body
        s.createContext("/set", ex -> {
            Map<String,String> m = q(ex.getRequestURI().getRawQuery());
            String body = new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
            rules.put(m.get("key"), new Rule(Integer.parseInt(m.getOrDefault("status","200")), body, Long.parseLong(m.getOrDefault("delay","0"))));
            send(ex, 200, "{}");
        });
        s.createContext("/log", ex -> { String all; synchronized(log){ all = String.join("\n", log);} send(ex, 200, all); });
        s.start();
        System.out.println("stub on " + a[0]);
    }
}
EOF
cd /tmp/run && (nohup java Stub.java 9099 > stub.log 2>&1 &) ; sleep 3; cat stub.log; curl -s 'localhost:9099/v2/quote?zip=1&weight_g=1&service=STD'

