cd /tmp/run && . ./h.sh
ts() { date -u -d "$1" +%Y-%m-%dT%H:%M:%SZ; }
stock() { curl -s $A/products/$1 | jq .stock; }
SEQ=${SEQ:-100}
newcpf() { SEQ=$((SEQ+1)); echo "91$(printf %09d $SEQ)"; }
order() { curl -s -X POST $A/orders -d "$(body "$1" STORE_PICKUP - PIX 1 BRONZE SOUTH $2)" | jq -r .id; }
pay() { curl -s -o /dev/null -w '%{http_code}' -X POST $1/orders/$2/payment -d "{\"transactionId\":\"TX-$2\",\"paidAt\":\"$(ts now)\"}"; }
setstock() { local s=$(stock $1); local d=$((s-$2)); if [ $d -gt 0 ]; then local o=$(order "[{\"sku\":\"$1\",\"quantity\":$d}]" $(newcpf)); pay $A $o >/dev/null; fi; }
# race label units n items-json-1 [items-json-2]  (items alternate between the two forms)
race() {
  local label=$1 units=$2 n=$3 it1=$4 it2=${5:-$4} skus=$6
  local ids=() cpfs=() args=()
  for k in $(seq 1 $n); do local c=$(newcpf); local it=$it1; [ $((k%2)) -eq 0 ] && it=$it2; local o=$(order "$it" $c); ids+=($o); cpfs+=($c); done
  local before=""; for s in $skus; do before="$before $s=$(stock $s)"; done
  local N=$(ts now); for k in $(seq 0 $((n-1))); do local u=$A; [ $((k%2)) -eq 1 ] && u=$B; args+=("$u/orders/${ids[$k]}/payment" "{\"transactionId\":\"TX-${ids[$k]}\",\"paidAt\":\"$N\"}"); done
  local dir=/tmp/run/c8_$SEQ; bash fire.sh $dir "${args[@]}"
  local ok=0 lost=0 other=0 badstate=0 notif=0
  for k in $(seq 0 $((n-1))); do
    local f=$dir/$((k+1)); local code=$(awk '{print $NF}' $f); local st=$(curl -s $B/orders/${ids[$k]} | jq -r .status)
    if [ $code = 200 ]; then ok=$((ok+1)); [ $st = PAID ] || badstate=$((badstate+1));
    elif grep -q '"INSUFFICIENT_STOCK"' $f && [ $code = 409 ]; then lost=$((lost+1)); [ $st = CANCELLED ] || badstate=$((badstate+1))
      local nc=$(curl -s $A/customers/${cpfs[$k]}/notifications | jq '[.[]|select(.type=="ORDER_CANCELLED")]|length'); [ $nc = 1 ] && notif=$((notif+1))
      [ -z "$REPLAYED" ] && { REPLAYED=1; echo "    replay loser on other machine: $(curl -s -w ' %{http_code}' -X POST $B/orders/${ids[$k]}/payment -d "{\"transactionId\":\"TX-${ids[$k]}\",\"paidAt\":\"$N\"}")"; }
    else other=$((other+1)); echo "    unexpected: $(cat $f)"; fi
  done
  local after=""; for s in $skus; do after="$after $s=$(stock $s)"; done
  echo "$label: units=$units orders=$n -> 200=$ok 409/INSUFFICIENT_STOCK=$lost other=$other wrong-status=$badstate loser-ORDER_CANCELLED=$notif/$lost stock[$before ] -> [$after ]"
}
REPLAYED=""
setstock MOC-001 1; race "MOC last unit" 1 2 '[{"sku":"MOC-001","quantity":1}]' '' MOC-001
setstock JAQ-001 2; race "JAQ 6 for 2" 2 6 '[{"sku":"JAQ-001","quantity":1}]' '' JAQ-001
for r in 1 2 3; do setstock CAM-001 1; race "CAM last unit #$r" 1 2 '[{"sku":"CAM-001","quantity":1}]' '' CAM-001; done
for r in 1 2 3; do setstock CAM-001 2; race "CAM 6 for 2 #$r" 2 6 '[{"sku":"CAM-001","quantity":1}]' '' CAM-001; done
for r in 1 2 3; do setstock MEI-001 2; race "MEI 6 for 2 #$r" 2 6 '[{"sku":"MEI-001","quantity":1}]' '' MEI-001; done
for r in 1 2; do setstock MEI-001 1; race "MEI 6 for 1 #$r" 1 6 '[{"sku":"MEI-001","quantity":1}]' '' MEI-001; done
setstock TEN-001 2; setstock FON-001 2; race "TEN+FON 6 for 2 (items in both orders)" 2 6 '[{"sku":"TEN-001","quantity":1},{"sku":"FON-001","quantity":1}]' '[{"sku":"FON-001","quantity":1},{"sku":"TEN-001","quantity":1}]' "TEN-001 FON-001"
echo "SEQ=$SEQ"
grep -c -i -E 'exception|deadlock' s1.log s2.log

